import {readFileSync,writeFileSync} from 'node:fs';
const source=readFileSync(new URL('../functions/_shared/tiebreaks.js',import.meta.url),'utf8');
const names=[...source.matchAll(/export (?:function|const) (\w+)/g)].map(m=>m[1]);
writeFileSync(new URL('../public/assets/tiebreaks.js',import.meta.url),
 '// Generated by scripts/build-tiebreaks.mjs. Do not edit.\nconst LeagueTiebreaks = (() => {\n'+source.replaceAll('export ','')+'\nreturn { '+names.join(', ')+' };\n})();\n');
// Plain JS keeps the deployed Pages builder compatible and avoids bundling the
// entire historical pick archive just to compare prior-season W/L.
const archive=JSON.parse(readFileSync(new URL('../public/data/seasons.json',import.meta.url),'utf8'));
const records=Object.fromEntries(Object.entries(archive.members).map(([name,years])=>[name,
 Object.fromEntries(Object.entries(years).map(([year,data])=>{
  const [W,L]=String(data.seasonRecord || '0-0').split('-').map(Number);return [year,{W:W||0,L:L||0}];
 }))]));
writeFileSync(new URL('../functions/_shared/historical-records.js',import.meta.url),
 '// Generated by scripts/build-tiebreaks.mjs from the historical archive.\nexport const historicalRecords = '+JSON.stringify(records,null,2)+';\n');
